(2,
 'Meta Hyperion',
 'Richland Parish, Louisiana',
 'Estados Unidos',
 32.450000,
 -91.640000,
 NULL,
 'Projeto gigante de IA da Meta que pode chegar a 5 GW.',
 'O Hyperion foi anunciado pela Meta no fim de 2024 em Richland Parish, uma região rural do nordeste da Louisiana. Em julho de 2025, Mark Zuckerberg disse que o projeto poderia chegar a 5 GW e que um único cluster ocuparia uma área comparável a uma parte significativa de Manhattan.

Os prazos variam conforme a fonte: a própria Meta falou em 2 GW de capacidade até 2030, crescendo para 5 GW nos anos seguintes, e reportagens de 2026 indicaram que a empresa pretende mais que dobrar o campus. Projetos desse tamanho exigem novas usinas de energia e linhas de transmissão construídas especialmente para eles.

O Hyperion também levantou debates locais sobre o uso de água e de energia, com números contestados pela Meta. A posição no mapa é aproximada.',
 'img/datacenters/richland.jpg',
 'Fórum de Richland Parish em Rayville, Louisiana. Não há foto do Hyperion com licença livre.',
