(10,
 'Stargate UAE',
 'Abu Dhabi',
 'Emirados Árabes Unidos',
 24.450000,
 54.380000,
 NULL,
 'Primeiro Stargate fora dos EUA, parte de um campus de IA de 5 GW em Abu Dhabi.',
 'Em maio de 2025 foi anunciado o Stargate UAE, primeiro projeto da iniciativa Stargate fora dos Estados Unidos. O cluster de 1 GW está sendo construído pela G42, empresa de tecnologia dos Emirados Árabes Unidos, e será operado pela OpenAI e pela Oracle, com sistemas Nvidia GB300, rede da Cisco e participação da SoftBank.

A primeira fase, de 200 MW, tinha conclusão prevista para 2026. O cluster faz parte de um campus muito maior em Abu Dhabi, com cerca de 26 km², planejado para receber até 5 GW de data centers de inteligência artificial no futuro.

O projeto mostra como os países do Golfo estão usando a riqueza do petróleo para investir em infraestrutura de IA. A localização exata não foi divulgada, por isso a posição no mapa é aproximada.',
 'img/datacenters/abu-dhabi.jpg',
 'Vista de Abu Dhabi a partir da ilha de Saadiyat. Não há foto do Stargate UAE com licença livre.',
 'comedian44',
